@Test/* maxWaitMillis x2 + padding */
@Timeout(value = 1200, unit = TimeUnit.MILLISECONDS)
public void testReturnBorrowObjectWithingMaxWaitMillis_1_oe() throws Exception {
    final long maxWaitMillis = 500;

    try (final GenericObjectPool<String> createSlowObjectFactoryPool = new GenericObjectPool<>(
            createSlowObjectFactory(60000))) {
        createSlowObjectFactoryPool.setMaxTotal(1);
        createSlowObjectFactoryPool.setMaxWaitMillis(maxWaitMillis);

        // thread1 tries creating a slow object to make pool full.
        final WaitingTestThread thread1 = new WaitingTestThread(createSlowObjectFactoryPool, 0);
        thread1.start();

        // Wait for thread1's reaching to create().
        Thread.sleep(100);

        // another one tries borrowObject. It should return within maxWaitMillis.
        assertThrows(NoSuchElementException.class, () -> createSlowObjectFactoryPool.borrowObject(maxWaitMillis), "borrowObject must fail due to timeout by maxWaitMillis");
}
}

@Test
public void testMakeObjectException_1_oe() throws Exception {
    final SimpleFactory<String> factory = new SimpleFactory<>();
    try (final GenericKeyedObjectPool<String, String> pool = new GenericKeyedObjectPool<>(factory)) {
        pool.setMaxTotalPerKey(1);
        pool.setBlockWhenExhausted(false);
        factory.exceptionOnCreate = true;
        assertThrows(Exception.class, () -> pool.borrowObject("One"));
}
}

@Test
public void testReturnObjectThrowsIllegalStateException_1_oe() {
    try (final GenericKeyedObjectPool<String, String> pool = new GenericKeyedObjectPool<>(new SimpleFactory<>())) {
        assertThrows(IllegalStateException.class, () ->  pool.returnObject("Foo", "Bar"));
}
}
